double SlatIdx(int which, double slatAng);
double SimpleGlazing(int which, double u, double shgc, int vtByUser, double vt);

/* The same functions under `rust_anything_` names, for shadow runs. */
double rust_anything_ScreenTrans(int which, int model, double gamma, double refl, double reflVis, double phi, double theta);
double rust_anything_RelPhiTheta(int which, double phiWin, double thetaWin, double sx, double sy, double sz);
double rust_anything_NormPhiTheta(int which, double phi, double theta);
double rust_anything_PhiThetaIdx(int which, double phi, double theta, double dPhi, double dTheta);
double rust_anything_ProfIdx(int which, double profAng);
double rust_anything_SlatIdx(int which, double slatAng);
double rust_anything_SimpleGlazing(int which, double u, double shgc, int vtByUser, double vt);

#endif /* MATOPTICS_RS_H */
